import java.util.*;

class Solution {
    public List<List<Integer>> pairs(int[] nums) {
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < nums.length; i += 2) {
            List<Integer> pair = new ArrayList<>();
            pair.add(nums[i]);
            pair.add(nums[i + 1]);
            res.add(pair);
        }
        return res;
    }
}

